-- State transitions declared for Registration: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION event.registrations_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('cancel', 'cancel'), ('cancel', 'done'), ('cancel', 'draft'), ('cancel', 'open'), ('done', 'cancel'), ('done', 'done'), ('done', 'draft'), ('done', 'open'), ('draft', 'cancel'), ('draft', 'done'), ('draft', 'draft'), ('draft', 'open'), ('open', 'cancel'), ('open', 'done'), ('open', 'draft'), ('open', 'open'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: registrations.state % -> %', OLD."state", NEW."state"
            USING ERRCODE = 'check_violation', COLUMN = 'state', CONSTRAINT = 'tg_registrations__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS registrations_state_transition_check ON event.registrations;
CREATE TRIGGER registrations_state_transition_check
    BEFORE UPDATE OF "state" ON event.registrations
    FOR EACH ROW EXECUTE FUNCTION event.registrations_state_transition_check();
